func (h *Handler) GetUsage(ctx context.Context, req UsageRequest) (*Usage, error) {
	caller, err := auth.CallerFrom(ctx)
	if err != nil {
		return nil, err
	}
	proj, err := h.store.Project(ctx, req.ProjectID)
	if err != nil {
		return nil, err
	}
	if proj.OwnerID != caller.UserID {
		return nil, ErrForbidden
	}
	return h.store.Usage(ctx, proj.ID)
}

