func (b *Builder) Daily(ctx context.Context, day time.Time) (*Summary, error) {
	total, count, err := b.store.Totals(ctx, day, day)
	if err != nil {
		return nil, err
	}
	if count == 0 {
		return nil, ErrNoExports
	}
	s := newSummary(total, count)
	return &s, nil
}

func (b *Builder) Monthly(ctx context.Context, month time.Time) (*Summary, error) {
	total, count, err := b.store.Totals(ctx, monthStart(month), monthEnd(month))
	if err != nil {
		return nil, err
	}
	if count <= 0 {
		return nil, ErrNoExports
	}
	s := newSummary(total, count)
	return &s, nil
}
